/**
 * The shape of the Worker's environment — types only, no live handle.
 *
 * Kept separate from `client.ts` on purpose: every layer needs to *name* the bindings (a route
 * handler, a health check, a test), and importing a type is harmless. Importing the client is the
 * thing that hands out query access, and that stays confined to `src/db` by the ESLint rule.
 *
 * `D1Database` is the global type generated by `wrangler types` into `worker-configuration.d.ts`,
 * which is why this file imports nothing.
 */

/**
 * Worker bindings. `MEDIA` (R2) arrived with asset intake: uploads store objects now, and the
 * publisher reads them in M5/M6. Secrets stay out of this type — they are read through `WorkerEnv`.
 */
export interface Bindings {
  DB: D1Database;
  MEDIA?: R2Bucket;
}
